<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageContentVO;

trait MessageContentAccessor
{
    private MessageContentVO $_content;
    public function getContent(): string
    {
        return $this->_content->value();
    }
    public function content(): MessageContentVO
    {
        return $this->_content;
    }
    public function isContentChanged(?self $original = null): bool
    {
        return !$this->_content->equals($original?->_content);
    }
    public function withContent(MessageContentVO|string $content): self
    {
        $copy = clone $this;
        $copy->_content = MessageContentVO::from($content);
        return $copy;
    }
}
